            (ENCODED_NON_ALPHA_NUMERIC_UNRESERVED ? "" : RFC3986_NON_ALPHANUMERIC_UNRESERVED_STR);
    private static final Set<Character> UNENCODED_SET = CollectionsUtil.strToUnmodifiableSet(UNENCODED_STR);

    /* Lookup table for hexadecimal conversion – immutable and thread‑safe */
    private static final char[] HEX_DIGITS = "0123456789ABCDEF".toCharArray();

    /**
     * Encode a character for URLs.
     *
     * @param immune characters that should not be encoded
     * @param c      character to encode
     * @return the percent‑encoded representation of {@code c}
     * @throws IllegalArgumentException if {@code c} is {@code null}
     */
    public String encodeCharacter(char[] immune, Character c) {
        Objects.requireNonNull(c, "Character to encode cannot be null");
        String cStr = c.toString();

        /* Allow callers to specify additional characters that should remain unencoded. */
        if (immune != null) {
            for (char ic : immune) {
                if (ic == c) {
                    return cStr;
                }
            }
        }

        /* RFC 3986 unreserved characters are left untouched. */
        if (UNENCODED_SET.contains(c)) {
            return cStr;
        }

        byte[] bytes = toUtf8Bytes(cStr);
        StringBuilder sb = new StringBuilder(bytes.length * 3);
        for (byte b : bytes) {
            appendTwoUpperHex(sb.append('%'), b);
        }
        return sb.toString();
    }

    /**
     * Append two upper‑case hexadecimal digits to the supplied {@link StringBuilder}.
     *
     * @param sb the builder to append to
     * @param b  the byte value to encode
     * @return the same {@link StringBuilder} instance for chaining
     */
    private static StringBuilder appendTwoUpperHex(StringBuilder sb, int b) {
        int unsignedByte = b & 0xFF;          // Convert signed byte to unsigned
        sb.append(HEX_DIGITS[unsignedByte >>> 4]);   // High nibble
        sb.append(HEX_DIGITS[unsignedByte & 0x0F]);  // Low nibble
        return sb;
    }

