static public File allocateFile(File dir, String name) throws IOException {
    if (dir == null || name == null) {
        throw new IllegalArgumentException("dir and name must not be null");
    }
    // Strip query string
    int q = name.indexOf('?');
    if (q > 0) {
        name = name.substring(0, q);
    }
    // Reject absolute paths or containing separators
    if (name.contains("/") || name.contains("\\") || name.contains("..")) {
        // Normalize path
        Path p = Paths.get(name).normalize();
        if (p.isAbsolute() || p.startsWith("..") || p.getNameCount() > 1) {
            throw new SecurityException("Invalid file name: " + name);
        }
        name = p.getFileName().toString(); // just base name
    }
    // Build file
    File file = new File(dir, name);
    // Ensure parent directories exist
    File parent = file.getParentFile();
    if (!parent.equals(dir)) { // but we already validated
    }
    // Resolve unique name
    String prefix, suffix;
    int dot = name.lastIndexOf('.');
    if (dot < 0) {
        prefix = name;
        suffix = "";
    } else {
        prefix = name.substring(0, dot);
        suffix = name.substring(dot);
    }
    int index = 2;
    while (file.exists()) {
        file = new File(dir, prefix + "-" + index++ + suffix);
    }
    // Create directories
    if (!file.getParentFile().exists()) {
        if (!file.getParentFile().mkdirs()) {
            throw new IOException("Failed to create directories for " + file);
        }
    }
    return file;
}
