     * @param name the requested file name (may come from untrusted sources)
     * @return a {@link File} object that does not yet exist
     * @throws IOException          if an I/O error occurs during canonicalisation
     * @throws SecurityException    if the name would cause a path traversal
     * @throws IllegalArgumentException if {@code dir} or {@code name} is {@code null}
     */
    static public File allocateFile(File dir, String name) throws IOException {
        if (dir == null || name == null) {
            throw new IllegalArgumentException("Directory and name must not be null");
        }

        // Strip query string if present
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        // Reject absolute paths or names containing path separators
