            }
            name = p.getFileName().toString();
        }

        // Construct the initial file reference
        File file = new File(dir, name);

        // Ensure the file stays within the intended directory
        File canonicalDir = dir.getCanonicalFile();
        File canonicalFile = file.getCanonicalFile();
        String dirPath = canonicalDir.getPath() + File.separator;
        if (!canonicalFile.getPath().startsWith(dirPath)) {
            throw new SecurityException("Attempt to escape directory: " + name);
        }

        // Resolve a unique filename if necessary
        String prefix;
        String suffix;
        int dot = name.lastIndexOf('.');
        if (dot < 0) {
            prefix = name;
            suffix = "";
        } else {
            prefix = name.substring(0, dot);
            suffix = name.substring(dot);
        }

        int index = 2;
        while (file.exists()) {
            file = new File(dir, prefix + "-" + index++ + suffix);
            canonicalFile = file.getCanonicalFile();
            if (!canonicalFile.getPath().startsWith(dirPath)) {
                throw new SecurityException("Attempt to escape directory during renaming");
            }
        }

        // Create parent directories if they do not exist
        File parent = file.getParentFile();
        if (!parent.exists() && !parent.mkdirs()) {
            throw new IOException("Failed to create directories for " + file);
        }

        return file;
    }

