    /**
     * Normalizes a URI path by ensuring it has exactly one leading slash.
     * <p>
     * The original implementation only removed excess leading slashes but never
     * guaranteed that a slash would remain. This could cause a path such as
     * {@code "foo"} to be interpreted as a host component when constructing a
     * {@link java.net.URI}. The patched method trims any number of leading
     * slashes, then guarantees a single leading slash unless the original
     * path was empty or consisted solely of slashes (in which case it returns
     * {@code "/"}). This preserves the original behaviour for empty strings
     * while preventing malformed URI construction.
     *
     * @param path the raw path component, may be {@code null}
     * @return a normalized path with a single leading slash, or {@code null}
     *         if the input was {@code null}
     */
    private static String normalizePath(final String path) {
        if (path == null) {
            return null;
        }

        // Count leading slashes
        int i = 0;
        while (i < path.length() && path.charAt(i) == '/') {
            i++;
        }

        // Remaining part after removing leading slashes
        final String remaining = path.substring(i);

        // If the original path was all slashes, return a single slash
        if (remaining.isEmpty() && i > 0) {
            return "/";
        }

        // If the path was empty (no slashes and no characters), preserve it
        if (remaining.isEmpty() && i == 0) {
            return "";
        }

        // Prepend a single slash to the trimmed path
        return '/' + remaining;
    }

