    /**
     * Creates a Locale object from the request param, which might
     * be already a Locale or a String. The method validates the
     * string representation against a strict whitelist to prevent
     * injection of arbitrary content that could lead to XSS or
     * other security issues.
     *
     * @param requestedLocale the parameter from the request
     * @return the Locale, or {@code null} if the input is invalid
     */
    protected Locale getLocaleFromParam(Object requestedLocale) {
        Locale locale = null;
        if (requestedLocale != null) {
            if (requestedLocale instanceof Locale) {
                locale = (Locale) requestedLocale;
            } else {
                String localeStr = requestedLocale.toString().trim();
                if (!localeStr.isEmpty() && VALID_LOCALE_PATTERN.matcher(localeStr).matches()) {
