public class DefaultActionMapper implements ActionMapper {

    private static final Logger LOG = LoggerFactory.getLogger(DefaultActionMapper.class);

    /**
     * Whitelist pattern for valid action names.
     * Only alphanumeric characters, dot, underscore, slash, exclamation mark,
     * and hyphen are permitted. The pattern is anchored implicitly by {@link Pattern#matcher(String).matches()}.
     */
    protected Pattern allowedActionNames = Pattern.compile("[a-zA-Z0-9._!\\/-]*");

