     * Otherwise a warning is logged and a safe default value is returned.
     * This approach eliminates the previous attempt to partially sanitize
     * the input, which could have left malicious fragments intact.
     *
     * @param rawActionName action name extracted from URI
     * @return a safe action name; an empty string is returned if the input is null or invalid
     */
    protected String cleanupActionName(final String rawActionName) {
        if (rawActionName == null) {
            if (LOG.isWarnEnabled()) {
                LOG.warn("Received null action name");
